#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,k,x;scanf("%d %d %d",&n,&k,&x);
vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
priority_queue<pair<long long,long long>>pq;
for(long long v:a){
pq.push({llabs(v-x),v});
if((int)pq.size()>k)pq.pop();}
vector<long long>res;
while(!pq.empty()){res.push_back(pq.top().second);pq.pop();}
sort(res.begin(),res.end());
for(int i=0;i<k;++i){if(i)printf(" ");printf("%lld",res[i]);}
printf("\n");return 0;}

